// ============================================================================
// FC_apb: APB4 register wrapper around FC_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/FC.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/FC.md
// ============================================================================
module FC_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tx_p,
  input logic rx_p
);
  localparam logic [31:0] ID_VALUE = 32'h46430200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [8:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd9) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [3:0]    c_cfg_credit;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [7:0]    c_tx_data;
  logic          c_tx_last;
  logic          c_tx_sofi;
  logic          c_tx_eoft;
  logic          c_tx_done;
  logic          c_tx_underrun;
  logic [3:0]    c_credit_used;
  logic          c_rx_valid;
  logic [7:0]    c_rx_data;
  logic          c_rx_last;
  logic [4:0]    c_rx_stat;
  logic          c_rx_frag;
  logic          c_rx_sync;
  logic          c_err_code;
  logic          c_err_word;
  FC_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .tx_p(tx_p),
    .rx_p(rx_p),
    .cfg_credit(c_cfg_credit),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_last(c_tx_last),
    .tx_sofi(c_tx_sofi),
    .tx_eoft(c_tx_eoft),
    .tx_done(c_tx_done),
    .tx_underrun(c_tx_underrun),
    .credit_used(c_credit_used),
    .rx_valid(c_rx_valid),
    .rx_data(c_rx_data),
    .rx_last(c_rx_last),
    .rx_stat(c_rx_stat),
    .rx_frag(c_rx_frag),
    .rx_sync(c_rx_sync),
    .err_code(c_err_code),
    .err_word(c_err_word)
  );

  // ---------------- registers ----------------
  logic [8:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [3:0] r_CFG;   // 12'h014 CFG
  logic [10:0] h_TX;   // 12'h018 TX holding register
  logic [13:0] h_RX;   // 12'h01C RX holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 4'h0;
      h_TX <= '0;
      h_RX <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[8:0] & wmask[8:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[6] && !full_TX) h_TX <= (h_TX & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[6] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[7]))) begin
        h_RX[7:0] <= c_rx_data[7:0];
        h_RX[8:8] <= c_rx_last;
        h_RX[13:9] <= c_rx_stat[4:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[7]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_credit = r_CFG[3:0];
  assign c_tx_data[7:0] = h_TX[7:0];
  assign c_tx_last = h_TX[8:8];
  assign c_tx_sofi = h_TX[9:9];
  assign c_tx_eoft = h_TX[10:10];
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_done;
    irq_set[1] = c_tx_underrun;
    irq_set[2] = c_rx_frag;
    irq_set[3] = c_err_code;
    irq_set[4] = c_err_word;
    irq_set[5] = full_TX & c_tx_ready;
    irq_set[6] = wr & (hit[6]) & full_TX;
    irq_set[7] = c_rx_valid & (~avail_RX | (rd & hit[7]));
    irq_set[8] = c_rx_valid & avail_RX & ~(rd & hit[7]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CFG);
      10'd6: rdata = 32'(h_TX);
      10'd7: rdata = 32'(h_RX);
      10'd8: rdata = 32'({c_credit_used, c_rx_sync});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
